using Store;

namespace ShoppingCart.Tests;

[TestClass]
public class ShoppingCartTests
{
    private Store.ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new Store.ShoppingCart();
    }

    #region AddItem Tests

    [TestMethod]
    public void AddItem_SingleItem_ItemIsAddedToCart()
    {
        _cart.AddItem("SKU-001", 2, 9.99m);

        var total = _cart.CalculateTotal();
        Assert.AreEqual(19.98m, total);
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_AllItemsContributeToTotal()
    {
        _cart.AddItem("SKU-001", 1, 10.00m);
        _cart.AddItem("SKU-002", 3, 5.00m);

        var total = _cart.CalculateTotal();
        Assert.AreEqual(25.00m, total);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_QuantitiesAccumulate()
    {
        _cart.AddItem("SKU-001", 1, 10.00m);
        _cart.AddItem("SKU-001", 2, 10.00m);

        var total = _cart.CalculateTotal();
        Assert.AreEqual(30.00m, total);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddItem_ZeroQuantity_ThrowsArgumentException()
    {
        _cart.AddItem("SKU-001", 0, 10.00m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddItem_NegativeQuantity_ThrowsArgumentException()
    {
        _cart.AddItem("SKU-001", -1, 10.00m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddItem_NegativePrice_ThrowsArgumentException()
    {
        _cart.AddItem("SKU-001", 1, -5.00m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddItem_NullSku_ThrowsArgumentException()
    {
        _cart.AddItem(null!, 1, 10.00m);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddItem_EmptySku_ThrowsArgumentException()
    {
        _cart.AddItem("", 1, 10.00m);
    }

    #endregion

    #region RemoveItem Tests

    [TestMethod]
    public void RemoveItem_ExistingItem_ItemRemovedFromCart()
    {
        _cart.AddItem("SKU-001", 2, 10.00m);
        _cart.RemoveItem("SKU-001");

        var total = _cart.CalculateTotal();
        Assert.AreEqual(0m, total);
    }

    [TestMethod]
    public void RemoveItem_OneOfMultipleItems_OnlySpecifiedItemRemoved()
    {
        _cart.AddItem("SKU-001", 1, 10.00m);
        _cart.AddItem("SKU-002", 1, 20.00m);
        _cart.RemoveItem("SKU-001");

        var total = _cart.CalculateTotal();
        Assert.AreEqual(20.00m, total);
    }

    [TestMethod]
    [ExpectedException(typeof(InvalidOperationException))]
    public void RemoveItem_NonExistentItem_ThrowsInvalidOperationException()
    {
        _cart.RemoveItem("SKU-NONEXISTENT");
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void RemoveItem_NullSku_ThrowsArgumentException()
    {
        _cart.RemoveItem(null!);
    }

    #endregion

    #region CalculateTotal Tests

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        var total = _cart.CalculateTotal();
        Assert.AreEqual(0m, total);
    }

    [TestMethod]
    public void CalculateTotal_SingleItemQuantityOne_ReturnsPriceTimesOne()
    {
        _cart.AddItem("SKU-001", 1, 15.50m);

        var total = _cart.CalculateTotal();
        Assert.AreEqual(15.50m, total);
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfAllLineItems()
    {
        _cart.AddItem("SKU-001", 2, 10.00m);
        _cart.AddItem("SKU-002", 1, 25.00m);
        _cart.AddItem("SKU-003", 5, 2.50m);

        var total = _cart.CalculateTotal();
        Assert.AreEqual(57.50m, total);
    }

    [TestMethod]
    public void CalculateTotal_AfterRemovingItem_ExcludesRemovedItem()
    {
        _cart.AddItem("SKU-001", 1, 10.00m);
        _cart.AddItem("SKU-002", 1, 20.00m);
        _cart.RemoveItem("SKU-002");

        var total = _cart.CalculateTotal();
        Assert.AreEqual(10.00m, total);
    }

    #endregion

    #region ApplyCoupon Tests

    [TestMethod]
    public void ApplyCoupon_ValidCode_ReducesTotal()
    {
        _cart.AddItem("SKU-001", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");

        var total = _cart.CalculateTotal();
        Assert.IsTrue(total < 100.00m, $"Expected total less than 100, got {total}");
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void ApplyCoupon_NullCode_ThrowsArgumentException()
    {
        _cart.ApplyCoupon(null!);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void ApplyCoupon_EmptyCode_ThrowsArgumentException()
    {
        _cart.ApplyCoupon("");
    }

    [TestMethod]
    [ExpectedException(typeof(InvalidOperationException))]
    public void ApplyCoupon_InvalidCode_ThrowsInvalidOperationException()
    {
        _cart.ApplyCoupon("INVALIDCOUPON");
    }

    [TestMethod]
    [ExpectedException(typeof(InvalidOperationException))]
    public void ApplyCoupon_ApplyTwice_ThrowsInvalidOperationException()
    {
        _cart.AddItem("SKU-001", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("SAVE10");
    }

    [TestMethod]
    public void ApplyCoupon_TotalNeverGoesNegative()
    {
        _cart.AddItem("SKU-001", 1, 1.00m);
        _cart.ApplyCoupon("SAVE10");

        var total = _cart.CalculateTotal();
        Assert.IsTrue(total >= 0m, $"Total should not be negative, got {total}");
    }

    #endregion
}

